#!/usr/bin/env bash
# Switch the focused monitor to one of its own workspace slots.
#
# Usage: switch-workspace.sh {focus|move} <slot>
#
# The monitor order and the workspace ranges are read from
# ~/.config/hypr/monitors.conf.sh, which is generated by install.sh from
# hosts/<host>/monitors.conf.sh. Nothing is hardcoded here.
set -euo pipefail

action="${1:-focus}"
num="${2:-1}"

if [[ ! "$num" =~ ^[0-9]+$ ]] || (( num < 1 )); then
    echo "usage: $0 {focus|move} <slot>" >&2
    exit 2
fi

conf="${XDG_CONFIG_HOME:-$HOME/.config}/hypr/monitors.conf.sh"
if [[ ! -r "$conf" ]]; then
    echo "switch-workspace: missing $conf (run install.sh --modules workspaces-split)" >&2
    exit 1
fi

MON_NAME=()
MON_WS_FIRST=()
MON_WS_COUNT=()

# shellcheck source=/dev/null
source "$conf"

if ! command -v hyprctl >/dev/null 2>&1; then
    echo "switch-workspace: hyprctl not found" >&2
    exit 1
fi

focused="$(hyprctl monitors -j | jq -r '.[] | select(.focused) | .name')"
if [[ -z "$focused" || "$focused" == "null" ]]; then
    echo "switch-workspace: cannot determine the focused monitor" >&2
    exit 1
fi

idx=-1
for i in "${!MON_NAME[@]}"; do
    if [[ "${MON_NAME[$i]}" == "$focused" ]]; then
        idx="$i"
        break
    fi
done

if (( idx < 0 )); then
    echo "switch-workspace: monitor '$focused' is not listed in $conf" >&2
    exit 1
fi

count="${MON_WS_COUNT[$idx]}"
if (( num > count )); then
    echo "switch-workspace: slot $num is out of range 1..$count for $focused" >&2
    exit 2
fi

target=$(( ${MON_WS_FIRST[$idx]} + num - 1 ))

case "$action" in
    focus)
        hyprctl dispatch "hl.dsp.focus({ workspace = $target })"
        ;;
    move)
        hyprctl dispatch "hl.dsp.window.move({ workspace = $target })"
        ;;
    *)
        echo "switch-workspace: unknown action '$action' (expected focus or move)" >&2
        exit 2
        ;;
esac
